--- 播放背景音乐
function CompeteMainDialog:PlayBGM()
    local comp = self:GetComponent()
    local index = comp:GetSelectPlayerPeopleIndex()
    local activityConf = comp:GetActivityConf()
    local song = activityConf.song
    local soundsId = song[index]
    if isNull(soundsId) then
        return
    end
    CriWareUtils.PlayMusicById(soundsId)
end

function CompeteMainDialog:StopBGM()
    CriWareUtils.StopLastBGMMusic()
    CriWareUtils.PlayRandomBGMFromCDList()
end

function CompeteMainDialog:PlayEnterAnimator()
    local comp = self:GetComponent()
    local people = comp:GetPeople()
    local playerPeopleId = checkInt(comp:GetPlayerPeopleId())
    local prefabId = tostring(comp:GetPrefabId())
    local index = 1
    for i, peopleId in pairs(people) do
        if checkInt(peopleId) == playerPeopleId then
            index = i
            break
        end
    end
    local animName = string.format("Enter_0%s", index)
    self.AnimationRoot:Play(Animator.StringToHash(Animators[prefabId][animName]), -1)
end

function CompeteMainDialog:PlayPkAnim()
    self.openPKCo = cs_coroutine.start(function()
        local parameters =  self.controller.Argument.parameters
        if not  isNull(parameters) then
            -- 选择角色界面进入的 ，说明是第一次进入 ， 第一次进入不播放领先动画
            local isChooseRole = parameters.isChooseRole
            if isChooseRole then
                return
            end
        end
        local comp = self:GetComponent()
        local day = os.date("%Y%m%d")
        local startDay = os.date("%Y%m%d" , comp:GetStartTime())
        -- 开始活动当天不播放领先奖励
        if day == startDay then
            return
        end

        local isEnd = comp:IsActivityEnd()
        local dialogConf = comp:GetPrefabDialogConf()
        -- 活动结束
        if isEnd then
            local isEndPlay = comp:GetIsEndDayEnter()
            if isEndPlay then
                -- 打开PK 界面
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
                UIModule.OpenDialog({id = dialogConf.PK_RESULT})
            end
            return
        end
        -- 每日首次进入播放一次领先动画
        local enterTime = comp:GetCurrentDayIsFirstEnter()
        if enterTime then
            -- 打开PK界面
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            UIModule.OpenDialog({id = dialogConf.PK_RESULT})
        end

    end)
end

function CompeteMainDialog:ClosePKDialog()
    local comp = self:GetComponent()
    --- 活动未结束 主界面不做任何处理
    if not comp:IsActivityEnd() then
        return
    end

    local isEndPlay = comp:IsPlayEndStoryId()
    if not isEndPlay then
        --TODO 播放剧情
        local endStoryId = comp:GetEndStoryId()
        local ChapterUtils = import('Game.Chapter.ChapterUtils')
        ChapterUtils.ProcessChapter(endStoryId, function(go)
            self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
            CS.UINavigationBarRoot.Instance:SetActive(false)
            comp:SetEnterEndStoryId()
            self._plotGo = go
        end, function()
            KTool.SafeDelete(self._plotGo)
            self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
            CS.UINavigationBarRoot.Instance:SetActive(true)
        end)
    end
end


-- 绑定组件
function CompeteMainDialog:BindComponent()
    local comp = self:GetComponent()
    for key, component in pairs(Components) do
        self[key] = comp:GetComponent(self.controller.gameObject, component)
    end
    for key, component in pairs(GameObjects) do
        self[key] = comp:GetGameObject(self.controller.gameObject, component)
    end
end
-- 绑定点击事件
function CompeteMainDialog:BindClick()
    local SetButtonAction = SetButtonAction
    SetButtonAction(self.GiveBtn, Bind(self, self.GivePointClick))
    SetButtonAction(self.RankBtn, Bind(self, self.RankClick))
    SetButtonAction(self.PointRewardBtn, Bind(self, self.PointRewardsClick))
    SetButtonAction(self.BtnTask, Bind(self, self.TaskClick))
    GameUtils.BindRedPoint(Constants.RedPointConst.CompeteGivePoint ,self.GiveBtn.gameObject)
    GameUtils.BindRedPoint(Constants.RedPointConst.CompeteTaskRewards ,self.BtnTask.gameObject )
    GameUtils.BindRedPoint(Constants.RedPointConst.CompetePointRewards ,self.PointRewardBtn.gameObject )
end
-- 更新UI 显示
function CompeteMainDialog:RefreshUI()
    local comp = self:GetComponent()
    local playerRank = comp:GetPlayerRank()
    local ranking = playerRank.ranking
    local point = checkInt(playerRank.point)
    local propId = comp:GetPropId()
    local ownNum = GoodsUtils.GetThingNo(propId)
    self.OwnGoodsTextNum.text = tostring(ownNum)
    self.RankingTextNum.text = tostring(ranking)
    self.GiveTextNum.text = tostring(point)
    local isEndActivity = comp:IsActivityEnd()
    if isEndActivity then
        KTool.SetActive(self.BtnTask.gameObject , false)
        ---@type Game.Native.Common.FontStyleButton
        local fontStyleBtn = KTool.GetComponent(self.GiveBtn.gameObject ,typeof(CS.Game.Native.Common.FontStyleButton) )
        if not isNull(fontStyleBtn) then
            fontStyleBtn:ResetFontStyle("B17" , localize("活动已结束"))
        end
    end
    local sprite = GoodsConfMgr:GetPhotoPathById(propId)
    self.ImgFlower:LoadSprite(sprite)
    self.GiveImgFlower:LoadSprite(sprite)
    CfUtils.FillText(self.TextTime2 , string.format("%s-%s" ,os.date("%m/%d" ,comp:GetStartTime()),os.date("%m/%d  %H:%M" ,comp:GetEndTime()) )   )
end

function CompeteMainDialog:DialogAndPlaySound()
    -- 如果携程存在 要先暂停携程
    if self.roleDialogCo then
        cs_coroutine.stop(self.roleDialogCo)
        self.roleDialogCo = nil
    end
    self.roleDialogCo = cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(3))
        KTool.SetActive(self.RoleDialogue, true)
        local comp = self:GetComponent()
        local giftConf = comp:GetPeopleGiftConf()
        local count = #giftConf
        local index = 1
        if count > 0 then
            index = math.random(1, count)
            self.RoleDialogueText.text = giftConf[index].test
        end
        local giftConf = comp:GetPeopleGiftConf()
        local voicecode = giftConf[index].voicecode
        if #voicecode > 0 then
            CriWareUtils.PlayMusicById(voicecode[1])
        end
        ---@type UnityEngine.Animation
        local animation = self.RoleDialogue:GetComponent(typeof(CS.UnityEngine.Animation))
        animation:PlayQueued('ThanksgivingMainDialog_RoleDialogue_enter', CS.UnityEngine.QueueMode.CompleteOthers)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
        animation:PlayQueued('ThanksgivingMainDialog_RoleDialogue_out', CS.UnityEngine.QueueMode.CompleteOthers)
    end)
end

