function CompeteMainDialog:FiveOClockUpdate()
    local comp = self:GetComponent()
    GameUtils.Request(Interfaces.ActivityUserPkHome, { activityUuid = comp:GetActivityUuid() }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data
            data.activityUuid = comp:GetActivityUuid()
            GameUtils.RemoveEntityCompByType(ECSComponentType.Constants.CompeteComponent)
            comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CompeteComponent)
            comp:Initial(data)
            self:RefreshUI()
            -- 广播刷新总的积分
            Events.Broadcast(Constants.EventNames.CompeteTotalPointRefresh)
            --- 刷新任务奖励领取界面
            local dialogConf = comp:GetPrefabDialogConf()
            local dialog = UIModule.CurrentScreen:GetDialog(dialogConf.TASK_DRAW)
            if not isNull(dialog) then
                ---@type CompeteTaskRewardsDialog
                local luaClass = dialog.Env
                luaClass:InitData()
                luaClass:RefreshView_()
            end
        end
    end)
end

