-- 赠送点数
function CompeteMainDialog:GivePointClick()
    local comp = self:GetComponent()
    local activityUuid = comp:GetActivityUuid()
    if comp:IsActivityEnd() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    local propId = comp:GetPropId()
    local goodsNum = GoodsUtils.GetThingNo(propId)
    if checkInt(goodsNum) <= 0 then
        GameUtils.Toast(localize("暂无道具"))
        return
    end
    GameUtils.Request(Interfaces.ActivityUserPkGivePoint, { activityUuid = activityUuid }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            KTool.SetActive(self.UIFX_SendFlower, false)
            KTool.SetActive(self.UIFX_SendFlower, true)
            local propId = comp:GetPropId()
            local goodsNum = GoodsUtils.GetThingNo(propId)
            -- 扣除所有道具
            GoodsUtils.DrawRewards({ { goodsId = propId, num = -goodsNum } })
            local data = response.data
            local playerRank = data.playerRank
            comp:SetPlayerRank(playerRank)
            comp:SetUserPkPointInfo(checkInt(data.totalPoint))
            self:RefreshUI()
            self:DialogAndPlaySound()
            -- 广播刷新总的积分
            Events.Broadcast(Constants.EventNames.CompeteTotalPointRefresh)
            self:SetPointRewards()
            self:SetGivePointRed()
        end
    end)
end
function CompeteMainDialog:RefreshRedPoint()
    self:SetGivePointRed()
    self:SetTaskRewards()
    self:SetPointRewards()
end
--- 赠送花术红点设置
function CompeteMainDialog:SetGivePointRed()
    local comp = self:GetComponent()
    local isActivityEnd = comp:IsActivityEnd()
    --- 活动已经结束
    if isActivityEnd then
        GameUtils.SetRedPointNum(Constants.RedPointConst.CompeteGivePoint , 0)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.CompeteGivePoint)
        return
    end

    local propId = comp:GetPropId()
    local goodsNum = GoodsUtils.GetThingNo(propId)
    if goodsNum > 0  then
        GameUtils.SetRedPointNum(Constants.RedPointConst.CompeteGivePoint , 1)
    else
        GameUtils.SetRedPointNum(Constants.RedPointConst.CompeteGivePoint , 0)
    end
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.CompeteGivePoint)
end


--- 领取任务红点设置
function CompeteMainDialog:SetTaskRewards()
    local comp = self:GetComponent()
    local isActivityEnd = comp:IsActivityEnd()
    --- 活动已经结束
    if isActivityEnd then
        GameUtils.SetRedPointNum(Constants.RedPointConst.CompeteTaskRewards , 0)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.CompeteTaskRewards)
        return
    end
    local isHaveDraw = false
    local comp = self:GetComponent()
    local taskConf =comp:GetTaskInfo()
    for i, v in pairs(taskConf) do
        if v.status == Constants.GetStatus.Can then
            isHaveDraw = true
            break
        end
    end
    if isHaveDraw  then
        GameUtils.SetRedPointNum(Constants.RedPointConst.CompeteTaskRewards , 1)
    else
        GameUtils.SetRedPointNum(Constants.RedPointConst.CompeteTaskRewards , 0)
    end
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.CompeteTaskRewards)
end


--- 领取点数奖励设置
function CompeteMainDialog:SetPointRewards()
    local isHaveDraw = false
    local comp = self:GetComponent()
    local pointRewards =comp:GetPointRewards()
    local status = 0
    for i, v in pairs(pointRewards) do
        status = comp:GetGrandPointStatusById(v.id)
        if status == Constants.GetStatus.Can then
            isHaveDraw = true
            break
        end
    end
    if isHaveDraw then

        GameUtils.SetRedPointNum(Constants.RedPointConst.CompetePointRewards , 1)
    else
        GameUtils.SetRedPointNum(Constants.RedPointConst.CompetePointRewards , 0)
    end
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.CompetePointRewards)
end

-- 任务获取
function CompeteMainDialog:TaskClick()
    local comp = self:GetComponent()
    if comp:IsActivityEnd() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    local dialogConf = comp:GetPrefabDialogConf()
    UIModule.OpenDialog({ id = dialogConf.TASK_DRAW })
end

function CompeteMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self:StopBGM()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end
return CompeteMainDialog